after.content:
plugins {
    application
}

dependencies {
    implementation(project(":ji-cli"))
}

application {
    mainClass.set("io.github.diodeme.ji.standalone.JiStandalone")
    applicationName = "ji-host"
}

tasks.named<CreateStartScripts>("startScripts") {
    doLast {
        unixScript.writeText(unixScript.readText().replace("DEFAULT_JVM_OPTS=\"\"", "DEFAULT_JVM_OPTS=\"-Dfile.encoding=UTF-8\""))
    }
}
